CREATE TABLE "product_post_sale_cost_cases" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "payment_id" uuid NOT NULL REFERENCES "product_payments"("id"), "reversal" varchar NOT NULL, "provider_case_id" varchar(255), "status" varchar NOT NULL DEFAULT 'open', "created_at" timestamp NOT NULL DEFAULT now(), "updated_at" timestamp NOT NULL DEFAULT now(), CONSTRAINT "product_post_sale_cost_cases_payment_reversal_unique" UNIQUE("payment_id", "reversal"));
CREATE TABLE "product_post_sale_cost_movements" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "case_id" uuid NOT NULL REFERENCES "product_post_sale_cost_cases"("id"), "provider_movement_id" varchar(255) NOT NULL, "kind" varchar NOT NULL, "attribution" varchar NOT NULL, "order_id" uuid REFERENCES "product_orders"("id"), "amount_centavos" integer NOT NULL, "supported_by" varchar NOT NULL, "observed_at" timestamp NOT NULL, "created_at" timestamp NOT NULL DEFAULT now(), CONSTRAINT "product_post_sale_cost_movements_provider_unique" UNIQUE("case_id", "provider_movement_id"));
CREATE INDEX "product_post_sale_cost_movements_case_idx" ON "product_post_sale_cost_movements"("case_id");
CREATE TABLE "product_post_sale_cost_settlements" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "case_id" uuid NOT NULL REFERENCES "product_post_sale_cost_cases"("id"), "debtor" varchar NOT NULL, "creditor" varchar NOT NULL, "amount_centavos" integer NOT NULL, "operator_user_id" uuid NOT NULL REFERENCES "users"("id"), "proof_url" text NOT NULL, "proof_key" varchar(255) NOT NULL, "confirmed_at" timestamp, "created_at" timestamp NOT NULL DEFAULT now(), CONSTRAINT "product_post_sale_cost_settlements_case_unique" UNIQUE("case_id"), CONSTRAINT "product_post_sale_cost_settlements_proof_unique" UNIQUE("proof_key"), CONSTRAINT "product_post_sale_cost_settlements_valid" CHECK ("debtor" <> "creditor" AND "amount_centavos" > 0));
